import java.util.*;

class Solution {
    public long maximumAffinity(int[] affinity, int[][] rules) {
        int n = affinity.length;
        Set<Integer> paired = new HashSet<>();
        long pairTotal = 0;
        for (int[] r : rules) {
            int a = r[0] - 1, b = r[1] - 1;
            paired.add(a); paired.add(b);
            pairTotal += Math.max(affinity[a], affinity[b]);
        }
        List<Integer> free = new ArrayList<>();
        for (int i = 0; i < n; i++) if (!paired.contains(i)) free.add(affinity[i]);
        free.sort(Collections.reverseOrder());
        long freeTotal = 0;
        int take = (free.size() + 1) / 2;
        for (int i = 0; i < take; i++) freeTotal += free.get(i);
        return pairTotal + freeTotal;
    }
}

#include <vector>
#include <algorithm>
#include <unordered_set>
using namespace std;

class Solution {
public:
    long long maximumAffinity(vector<int>& affinity, vector<vector<int>>& rules) {
        int n = affinity.size();
        unordered_set<int> paired;
        long long pairTotal = 0;
        for (auto& r : rules) {
            int a = r[0] - 1, b = r[1] - 1;
            paired.insert(a); paired.insert(b);
            pairTotal += max(affinity[a], affinity[b]);
        }
        vector<int> freeVals;
        for (int i = 0; i < n; i++) if (!paired.count(i)) freeVals.push_back(affinity[i]);
        sort(freeVals.begin(), freeVals.end(), greater<int>());
        long long freeTotal = 0;
        int take = (freeVals.size() + 1) / 2;
        for (int i = 0; i < take; i++) freeTotal += freeVals[i];
        return pairTotal + freeTotal;
    }
};
